window.AUTH=window.AUTH||{};window.AUTH["21-1449"]={"d":"21-1449","id":"2022/21-1449","n":"Glacier Northwest, Inc. v. International Brotherhood of Teamsters","briefs":[{"k":"petitioner","label":"Brief of petitioner Glacier Northwest, Inc., d/b/a CalPortland","date":"2022-11-01","url":"https://www.supremecourt.gov/DocketPDF/21/21-1449/244536/20221101152235433_21-1449%20-%20Brief%20for%20Petitioner.pdf","side":"pet","n":52},{"k":"united-states","label":"Brief amicus curiae of United States in support of neither party","date":"2022-11-08","url":"https://www.supremecourt.gov/DocketPDF/21/21-1449/246034/20221108133338239_21-1449npacUnitedStates.pdf","side":"us","n":54},{"k":"respondent","label":"Brief of respondent International Brotherhood of Teamsters Local Union No. 174","date":"2022-12-01","url":"https://www.supremecourt.gov/DocketPDF/21/21-1449/248846/20221201134527353_21-1449bs%20-%20for%20filing.pdf","side":"res","n":114},{"k":"reply","label":"Reply of petitioner Glacier Northwest, Inc., d/b/a CalPortland","date":"2022-12-30","url":"https://www.supremecourt.gov/DocketPDF/21/21-1449/251116/20221230120611119_21-1449%20merits%20rb.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us2r32_ca7d.pdf","tr":true,"items":[{"t":"case","label":"Amalgamated Ass’n of St., Elec. Ry. & Motor Coach Emps. of Am. v. Lockridge","cite":"403 U.S. 274","y":1971,"id":"1970/76","sc":1,"sum":"Respondent, who had been discharged from employment on the ground that he had forfeited his good standing membership in petitioner Union by dues arrearage and was therefore subject to termination under the union security clause in the applicable collective-bargaining agreement, brought suit in the state court against the Union and the employer (which was later dropped as a party). The two-count complaint charged (1) …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46","1":"30","2":"17, 34, 38","3":"10"}},{"t":"case","label":"Aschermann v. Philip Best Brewing Co.","cite":"45 Wis. 262","y":1878,"url":"https://www.courtlistener.com/c/Wis./45/262/","by":{"0":"39"}},{"t":"case","label":"Barbieri v. United Techs. Corp.","cite":"771 A.2d 915","y":2001,"court":"Conn.","url":"https://www.courtlistener.com/c/A.2d/771/915/","by":{"0":"28"}},{"t":"case","label":"Beaman v. Yakima Valley Disposal, Inc.","cite":"807 P.2d 849","y":1991,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/807/849/","sum":"Describing Garmon dismissal as jurisdictional, not on the merits.","sumSrc":"brief:2","by":{"0":"11","2":"11"}},{"t":"case","label":"Bill Johnson’s Rests., Inc. v. NLRB","cite":"461 U.S. 731","y":1983,"id":"1982/81-2257","sc":1,"op":1,"sum":"After one Helton, a waitress at petitioner's restaurant, filed unfair labor practice charges with the National Labor Relations Board (NLRB) alleging that she had been fired because of her efforts to organize a union, Helton and others, including other waitresses, picketed the restaurant and distributed leaflets. Petitioner and three of its co-owners then filed a suit for damages and injunctive relief against Helton …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 25, 45, 46","2":"19, 44","3":"2, 17, 18, 19, 20, 22, 23"}},{"t":"case","label":"Cedar Point Nursery v. Hassid","cite":"141 S. Ct. 2063","y":2021,"id":"2020/20-107","sc":1,"sum":"A California regulation granting labor organizations a “right to take access” to an agricultural employer’s property to solicit support for unionization constitutes a per se physical taking.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"47, 48","2":"48, 49","3":"13, 20"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Nat. Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"City Line Open Hearth, Inc. v. Hotel, Motel & Club Emps.’ Union Loc. No. 568","cite":"413 Pa. 420","y":1964,"url":"https://www.courtlistener.com/c/Pa./413/420/","by":{"0":"27"}},{"t":"case","label":"Columbia Portland Cement Co. v. NLRB","cite":"915 F.2d 253","y":1990,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/915/253/","op":2,"by":{"0":"32, 35","1":"16","2":"28, 29, 30"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"sum":"(1) As the claims are governed by the maritime law and within the admiralty jurisdiction, trial by jury is not required by the Seventh Amendment. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Del. & Hudson Ry. Co. v. United Transp. Union","cite":"450 F.2d 603","y":1971,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/450/603/","sum":"Interpreting Railway Labor Act, not NLRA.","sumSrc":"brief:2","by":{"0":"22","2":"26"}},{"t":"case","label":"Eley v. Mid/E. Acceptance Corp. of N.C., Inc.","cite":"614 S.E.2d 555","y":2005,"court":"N.C. Ct. App.","url":"https://www.courtlistener.com/c/S.E.2d/614/555/","by":{"0":"39"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Falls Stamping & Welding Co. v. Int’l Union, United Auto. Workers, Aerospace & Agric. Implement Workers of Am.","cite":"744 F.2d 521","y":1984,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/744/521/","by":{"0":"36"}},{"t":"case","label":"Farmer v. United Bhd. of Carpenters & Joiners of Am., Loc. 25","cite":"430 U.S. 290","y":1977,"id":"1976/75-804","sc":1,"sum":"A member and officer (petitioner's decedent) of respondent local carpenters' Union brought a tort action for damages in California state court against respondent Unions and Union officials, alleging in count two of the complaint that, because of a sharp disagreement between him and Union officials over various internal Union policies, respondents had intentionally engaged in outrageous conduct, threats, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 26, 27, 29, 34, 40, 44, 45, 46","1":"29","2":"13, 32, 34, 47","3":"16, 19, 20, 22, 23"}},{"t":"case","label":"Haberman v. Wash. Pub. Power Supply Sys.","cite":"744 P.2d 1032","y":1987,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/744/1032/","by":{"0":"7"}},{"t":"case","label":"Int’l Longshoremen’s Ass’n v. Davis","cite":"476 U.S. 380","y":1986,"id":"1985/85-217","sc":1,"op":12,"sum":"Appellee was formerly employed as a ship superintendent for a stevedoring company. When he, with others, attempted to organize the company's ship superintendents and to affiliate with appellant Union, a union official allegedly assured them that the Union would get them their jobs back if they were discharged for participating in union-related activities. After he was discharged apparently because of such …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 6, 11, 14, 17, 32, 33","1":"3, 4, 24, 25, 30","2":"passim","3":"21"}},{"t":"case","label":"Int’l Union, United Auto., Aircraft & Agric. Implement Workers of Am. v. Russell","cite":"356 U.S. 634","y":1958,"id":"1957/21","sc":1,"sum":"Reiterated the Supreme Court’s decision in United Construction Workers v. Laburnum Corp. , which held that Congress did not give the National Labor Relations Board exclusive jurisdiction over a common-law tort for damages.","sumSrc":"Oyez","by":{"0":"5, 24","2":"33, 34"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"47","2":"48, 50"}},{"t":"case","label":"Kansas v. Garcia","cite":"140 S. Ct. 791","y":2020,"id":"2019/17-834","sc":1,"sum":"A case in which the Court upheld Kansas's prosecution of noncitizens who used stolen social security numbers to gain employment.","sumSrc":"Oyez","by":{"0":"42, 43, 44, 46","2":"45"}},{"t":"case","label":"Kinney v. Cook","cite":"154 P.3d 206","y":2007,"court":"Wash.","url":"https://www.courtlistener.com/c/P.3d/154/206/","op":1,"by":{"0":"7"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"33"}},{"t":"case","label":"Lechmere, Inc. v. NLRB","cite":"502 U.S. 527","y":1992,"id":"1991/90-970","sc":1,"sum":"Reasoned Justice Clarence Thomas, except in situations where inaccessibility makes communication through normal channels ineffective. There were alternatives short of trespass, such as signs, mailings, and newspaper ads. (Thomas's defense of private property rights may offer a clue to his budding jurisprudence.).","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Linn v. United Plant Guard Workers of Am., Loc. 114","cite":"383 U.S. 53","y":1966,"id":"1965/45","sc":1,"op":1,"sum":"Where a party to a labor dispute circulates false and defamatorv statements during a union organizing campaign the court has jurisdiction to apply state remedies if the complainant pleads and proves that the statements were made with malice and injured him.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 26, 27, 33, 34, 37, 40, 44, 46","1":"29","2":"34","3":"10, 12, 15, 17, 19, 20, 22, 23"}},{"t":"case","label":"Lodge 76, Int’l Ass’n of Machinists & Aerospace Workers v. Wis. Emp. Rels. Comm’n","cite":"427 U.S. 132","y":1976,"id":"1975/75-185","sc":1,"op":1,"sum":"The union's concerted refusal to work overtime was peaceful conduct constituting activity that must be free of state regulation if the congressional intent in enacting the comprehensive federal law of labor relations is not to be frustrated. Congress meant that self-help economic activities, whether of employer or employee, were not to be regulable by States any more than by the NLRB, for neither States nor the NLRB …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 9, 15, 23, 25, 37, 38, 39, 43","2":"21"}},{"t":"case","label":"Loretto v. Teleprompter Manhattan CATV Corp.","cite":"458 U.S. 419","y":1982,"id":"1981/81-244","sc":1,"sum":"The New York statute works a taking of a portion of appellant's property for which she is entitled to just compensation under the Fifth Amendment, as made applicable to the States by the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Miss. Gulf Coast Bldg. & Constr. Trades Council v. Brown & Root, Inc.","cite":"417 So. 2d 564","y":1982,"court":"Miss.","url":"https://www.courtlistener.com/c/So.%202d/417/564/","by":{"0":"27"}},{"t":"case","label":"NLRB v. A. Lasaponara & Sons, Inc.","cite":"541 F.2d 992","y":1976,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/541/992/","by":{"0":"36","2":"23, 24, 25, 26","3":"9"}},{"t":"case","label":"NLRB v. Babcock & Wilcox Co.","cite":"351 U.S. 105","y":1956,"id":"1955/250","sc":1,"sum":"In the circumstances of these cases, the nondiscriminatory refusal of the employers to permit distribution of union literature by nonemployee union organizers on company-owned parking lots. did not unreasonably impede their employees' right to self-organization in violation of § 8 (a) (1) of the National Labor Relations Act, because the locations of the plants and of the living quarters of the employees did not …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47, 48","3":"20"}},{"t":"case","label":"NLRB v. Fansteel Metallurgical Corp.","cite":"306 U.S. 240","y":1939,"id":"scdb/1938-054","sc":1,"op":3,"sum":"1. Seizure and forcible retention of an employer's factory buildings by employees, in a \"sit-down\" strike, is good cause for their discharge.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 20, 21, 24, 34, 35, 37, 43, 44","1":"13","2":"33, 34, 46","3":"4, 13"}},{"t":"case","label":"NLRB v. Loc. Union No. 1229, Int’l Bhd. of Elec. Workers","cite":"346 U.S. 464","y":1953,"id":"scdb/1953-017","sc":1,"op":2,"sum":"Upon the facts of this case, the discharge of certain employees by their employer did not constitute an unfair labor practice within the meaning of §§ 8 (a) (1) and 7 of the Taft-Hartley Act; their discharge was \"for cause\" within the meaning of § 10 (c) of that Act, and the action of the Labor Board in not requiring their reinstatement is here sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 19","2":"26"}},{"t":"case","label":"NLRB v. Marsden","cite":"701 F.2d 238","y":1983,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/701/238/","by":{"0":"22","2":"26"}},{"t":"case","label":"NLRB v. Marshall Car Wheel & Foundry Co.","cite":"218 F.2d 409","y":1955,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/218/409/","op":2,"by":{"0":"10, 20, 21, 22, 31","1":"14","2":"29","3":"5, 6"}},{"t":"case","label":"NLRB v. Morris Fishman & Sons, Inc.","cite":"278 F.2d 792","y":1960,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/278/792/","by":{"0":"20, 32","3":"5"}},{"t":"case","label":"Pa. Nurses Ass’n v. Pa. State Educ. Ass’n","cite":"90 F.3d 797","y":1996,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/90/797/","by":{"0":"27, 28"}},{"t":"case","label":"People v. Cook","cite":"1998 WL 1990468","y":1998,"court":"Mich. Ct. App. July 31","by":{"0":"39"}},{"t":"case","label":"Rockford Redi-Mix, Inc. v. Teamsters Loc. 325, Gen. Chauffeurs, Helpers & Sales Drivers of Rockford","cite":"551 N.E.2d 1333","y":1990,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.2d/551/1333/","by":{"0":"28","2":"33, 34"}},{"t":"case","label":"San Diego Building Trades Council v. Garmon","cite":"359 U.S. 236","y":1959,"id":"1958/66","sc":1,"op":16,"sum":"Although the National Labor Relations Board had declined to exercise jurisdiction, a California state court was precluded by the National Labor Relations Act from awarding damages to respondents under state law for economic injuries resulting from the peaceful picketing of their plant by labor unions which had not been selected by a majority of respondents' employees as their bargaining agents.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"1, 2, 5, 6, 9, 12, 14, 15, 16, 17, 18, 19, 20, 23, 24, 25, 26, 27, 28, 29, 34, 37, 38, 39, 40, 41, 42, 43, 44, 46","1":"passim","2":"passim","3":"1, 2, 3, 14, 15, 20, 21, 22, 23"}},{"t":"case","label":"Sears, Roebuck & Co. v. San Diego Cnty. Dist. Council of Carpenters","cite":"436 U.S. 180","y":1978,"id":"1977/76-750","sc":1,"op":5,"ar":1,"sum":"Upon determining that certain carpentry work in petitioner's department store was being done by men who had not been dispatched from its hiring hall, respondent Union established picket lines on petitioner's property. When the Union refused petitioner's demand to remove the pickets, petitioner filed suit in the California Superior Court and obtained a preliminary injunction against the continuing trespass, and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 37","1":"4","2":"passim","3":"20"}},{"t":"case","label":"U.S. Steel Co. (Joliet Coke Works) v. NLRB","cite":"196 F.2d 459","y":1952,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/196/459/","by":{"0":"21","2":"29"}},{"t":"case","label":"United Auto., Aircraft & Agric. Implement Workers of Am. v. Wis. Emp. Rels. Bd.","cite":"351 U.S. 266","y":1956,"id":"1955/530","sc":1,"sum":"The order of the State Board is valid and the judgment of the State Court enforcing it is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","2":"33"}},{"t":"case","label":"United Constr. Workers, Affiliated with United Mine Workers of Am. v. Laburnum Constr. Corp.","cite":"347 U.S. 656","y":1954,"id":"scdb/1953-083","sc":1,"op":1,"sum":"The Act did not give to the National Labor Relations Board such exclusive jurisdiction over the subject matter of the action as to preclude the state court from hearing and determining the issues.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 15, 23, 24, 25, 26, 27, 35, 38, 39, 40, 43, 44, 47","1":"29","2":"34","3":"6"}},{"t":"case","label":"United Food & Com. Workers Int’l Union v. Wal-Mart Stores, Inc.","cite":"162 A.3d 909","y":2017,"court":"Md.","url":"https://www.courtlistener.com/c/A.3d/162/909/","by":{"0":"28"}},{"t":"case","label":"United Food & Com. Workers Int’l Union v. Wal-Mart Stores, Inc.","cite":"504 S.W.3d 573","y":2016,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.3d/504/573/","by":{"0":"28"}},{"t":"case","label":"Va. Uranium, Inc. v. Warren","cite":"139 S. Ct. 1894","y":2019,"id":"2018/16-1275","sc":1,"sum":"The Fourth Circuit’s judgment that the Atomic Energy Act does not preempt Virginia’s prohibition on uranium mining in the Commonwealth is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"43","2":"45"}},{"t":"case","label":"Weber v. Anheuser-Busch, Inc.","cite":"348 U.S. 468","y":1955,"id":"scdb/1954-045","sc":1,"op":1,"sum":"The state court was without jurisdiction to enjoin the conduct of the union, since its jurisdiction had been pre-empted by the authority vested in the National Labor Relations Board.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"op":1,"ar":1,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"0":"42, 43","2":"45"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","by":{"0":"3"}},{"t":"usc","label":"29 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/29/151","stext":{"head":"§151. Findings and declaration of policy","paras":[[0,"The denial by some employers of the right of employees to organize and the refusal by some employers to accept the procedure of collective bargaining lead to strikes and other forms of industrial strife or unrest, which have the intent or the necessary effect of burdening or obstructing commerce by (a) impairing the efficiency, safety, or operation of the instrumentalities of commerce; (b) occurring in the current of commerce; (c) materially affecting, restraining, or controlling the flow of raw materials or manufactured or processed goods from or into the channels of commerce, or the prices of such materials or goods in commerce; or (d) causing diminution of employment and wages in such volume as substantially to impair or disrupt the market for goods flowing from or into the channels of commerce."],[0,"The inequality of bargaining power between employees who do not possess full freedom of association or actual liberty of contract, and employers who are organized in the corporate or other forms of ownership association substantially burdens and affects the flow of commerce, and tends to aggravate recurrent business depressions, by depressing wage rates and the purchasing power of wage earners in industry and by preventing the stabilization of competitive wage rates and working conditions within and between industries."],[0,"Experience has proved that protection by law of the right of employees to organize and bargain collectively safeguards commerce from injury, impairment, or interruption, and promotes the flow of commerce by removing certain recognized sources of industrial strife and unrest, by encouraging practices fundamental to the friendly adjustment of industrial disputes arising out of differences as to wages, hours, or other working conditions, and by restoring equality of bargaining power between employers and employees."],[0,"Experience has further demonstrated that certain practices by some labor organizations, their officers, and members have the intent or the necessary effect of burdening or obstructing commerce by preventing the free flow of goods in such commerce through strikes and other forms of industrial unrest or through concerted activities which impair the interest of the public in the free flow of such commerce. The elimination of such practices is a necessary condition to the assurance of the rights herein guaranteed."],[0,"It is hereby declared to be the policy of the United States to eliminate the causes of certain substantial obstructions to the free flow of commerce and to mitigate and eliminate these obstructions when they have occurred by encouraging the practice and procedure of collective bargaining and by protecting the exercise by workers of full freedom of association, self-organization, and designation of representatives of their own choosing, for the purpose of negotiating the terms and conditions of their employment or other mutual aid or protection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/151?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":1,"head":"§151. Findings and declaration of policy","tname":"Labor","by":{"0":"4","1":"1, 2","2":"1, 3, 4, 25","3":"12"}},{"t":"usc","label":"29 U.S.C. § 157","url":"https://www.law.cornell.edu/uscode/text/29/157","stext":{"head":"§157. Right of employees as to organization, collective bargaining, etc.","paras":[[0,"Employees shall have the right to self-organization, to form, join, or assist labor organizations, to bargain collectively through representatives of their own choosing, and to engage in other concerted activities for the purpose of collective bargaining or other mutual aid or protection, and shall also have the right to refrain from any or all of such activities except to the extent that such right may be affected by an agreement requiring membership in a labor organization as a condition of employment as authorized in section 158(a)(3) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/157?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§157. Right of employees as to organization, collective bargaining, etc.","tname":"Labor","by":{"0":"3, 4, 18","1":"2, 5, 11, 28, 29","2":"1, 3, 21, 46"}},{"t":"usc","label":"29 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/29/158","subs":["(a)(1)","(b)","(b)(1)(A)","(b)(4)","(b)(4)(B)","(d)","(d)(1)","(d)(4)","(g)"],"stext":{"head":"§158. Unfair labor practices","paras":[[0,"(a) Unfair labor practices by employer"],[0,"It shall be an unfair labor practice for an employer—"],[1,"(1) to interfere with, restrain, or coerce employees in the exercise of the rights guaranteed in section 157 of this title;"],[1,"(2) to dominate or interfere with the formation or administration of any labor organization or contribute financial or other support to it: Provided, That subject to rules and regulations made and published by the Board pursuant to section 156 of this title, an employer shall not be prohibited from permitting employees to confer with him during working hours without loss of time or pay;"],[1,"(3) by discrimination in regard to hire or tenure of employment or any term or condition of employment to encourage or discourage membership in any labor organization: Provided, That nothing in this subchapter, or in any other statute of the United States, shall preclude an employer from making an agreement with a labor organization (not established, maintained, or assisted by any action defined in this subsection as an unfair labor practice) to require as a condition of employment membership therein on or after the thirtieth day following the beginning of such employment or the effective date of such agreement, whichever is the later, (i) if such labor organization is the representative of the employees as provided in section 159(a) of this title, in the appropriate collective-bargaining unit covered by such agreement when made, and (ii) unless following an election held as provided in section 159(e) of this title within one year preceding the effective date of such agreement, the Board shall have certified that at least a majority of the employees eligible to vote in such election have voted to rescind the authority of such labor organization to make such an agreement: Provided further, That no employer shall justify any discrimination against an employee for nonmembership in a labor organization (A) if he has reasonable grounds for believing that such membership was not available to the employee on the same terms and conditions generally applicable to other members, or (B) if he has reasonable grounds for believing that membership was denied or terminated for reasons other than the failure of the employee to tender the periodic dues and the initiation fees uniformly required as a condition of acquiring or retaining membership;"],[1,"(4) to discharge or otherwise discriminate against an employee because he has filed charges or given testimony under this subchapter;"],[1,"(5) to refuse to bargain collectively with the representatives of his employees, subject to the provisions of section 159(a) of this title."],[0,"(b) Unfair labor practices by labor organization"],[0,"It shall be an unfair labor practice for a labor organization or its agents—"],[1,"(1) to restrain or coerce (A) employees in the exercise of the rights guaranteed in section 157 of this title: Provided, That this paragraph shall not impair the right of a labor organization to prescribe its own rules with respect to the acquisition or retention of membership therein; or (B) an employer in the selection of his representatives for the purposes of collective bargaining or the adjustment of grievances;"],[1,"(2) to cause or attempt to cause an employer to discriminate against an employee in violation of subsection (a)(3) or to discriminate against an employee with respect to whom membership in such organization has been denied or terminated on some ground other than his failure to tender the periodic dues and the initiation fees uniformly required as a condition of acquiring or retaining membership;"],[1,"(3) to refuse to bargain collectively with an employer, provided it is the representative of his employees subject to the provisions of section 159(a) of this title;"],[1,"(4)(i) to engage in, or to induce or encourage any individual employed by any person engaged in commerce or in an industry affecting commerce to engage in, a strike or a refusal in the course of his employment to use, manufacture, process, transport, or otherwise handle or work on any goods, articles, materials, or commodities or to perform any services; or (ii) to threaten, coerce, or restrain any person engaged in commerce or in an industry affecting commerce, where in either case an object thereof is—"],[2,"(A) forcing or requiring any employer or self-employed person to join any labor or employer organization or to enter into any agreement which is prohibited by subsection (e);"],[2,"(B) forcing or requiring any person to cease using, selling, handling, transporting, or otherwise dealing in the products of any other producer, processor, or manufacturer, or to cease doing business with any other person, or forcing or requiring any other employer to recognize or bargain with a labor organization as the representative of his employees unless such labor organization has been certified as the representative of such employees under the provisions of section 159 of this title: Provided, That nothing contained in this clause (B) shall be construed to make unlawful, where not otherwise unlawful, any primary strike or primary picketing;"],[2,"(C) forcing or requiring any employer to recognize or bargain with a particular labor organization as the representative of his employees if another labor organization has been certified as the representative of such employees under the provisions of section 159 of this title;"],[2,"(D) forcing or requiring any employer to assign particular work to employees in a particular labor organization or in a particular trade, craft, or class rather than to employees in another labor organization or in another trade, craft, or class, unless such employer is failing to conform to an order or certification of the Board determining the bargaining representative for employees performing such work:"],[1,"Provided, That nothing contained in this subsection shall be construed to make unlawful a refusal by any person to enter upon the premises of any employer (other than his own employer), if the employees of such employer are engaged in a strike ratified or approved by a representative of such employees whom such employer is required to recognize under this subchapter: Provided further, That for the purposes of this paragraph (4) only, nothing contained in such paragraph shall be construed to prohibit publicity, other than picketing, for the purpose of truthfully advising the public, including consumers and members of a labor organization, that a product or products are produced by an employer with whom the labor organization has a primary dispute and are distributed by another employer, as long as such publicity does not have an effect of inducing any individual employed by any person other than the primary employer in the course of his employment to refuse to pick up, deliver, or transport any goods, or not to perform any services, at the establishment of the employer engaged in such distribution;"],[1,"(5) to require of employees covered by an agreement authorized under subsection (a)(3) the payment, as a condition precedent to becoming a member of such organization, of a fee in an amount which the Board finds excessive or discriminatory under all the circumstances. In making such a finding, the Board shall consider, among other relevant factors, the practices and customs of labor organizations in the particular industry, and the wages currently paid to the employees affected;"],[1,"(6) to cause or attempt to cause an employer to pay or deliver or agree to pay or deliver any money or other thing of value, in the nature of an exaction, for services which are not performed or not to be performed; and"],[1,"(7) to picket or cause to be picketed, or threaten to picket or cause to be picketed, any employer where an object thereof is forcing or requiring an employer to recognize or bargain with a labor organization as the representative of his employees, or forcing or requiring the employees of an employer to accept or select such labor organization as their collective bargaining representative, unless such labor organization is currently certified as the representative of such employees:"],[2,"(A) where the employer has lawfully recognized in accordance with this subchapter any other labor organization and a question concerning representation may not appropriately be raised under section 159(c) of this title,"],[2,"(B) where within the preceding twelve months a valid election under section 159(c) of this title has been conducted, or"],[2,"(C) where such picketing has been conducted without a petition under section 159(c) of this title being filed within a reasonable period of time not to exceed thirty days from the commencement of such picketing: Provided, That when such a petition has been filed the Board shall forthwith, without regard to the provisions of section 159(c)(1) of this title or the absence of a showing of a substantial interest on the part of the labor organization, direct an election in such unit as the Board finds to be appropriate and shall certify the results thereof: Provided further, That nothing in this subparagraph (C) shall be construed to prohibit any picketing or other publicity for the purpose of truthfully advising the public (including consumers) that an employer does not employ members of, or have a contract with, a labor organization, unless an effect of such picketing is to induce any individual employed by any other person in the course of his employment, not to pick up, deliver or transport any goods or not to perform any services."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/158?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§158. Unfair labor practices","tname":"Labor","by":{"0":"3, 4","1":"2, 5, 11, 28, 29, 2, 29, 2","2":"4, 4, 26, 4, 28, 28, 4","3":"7"}},{"t":"usc","label":"29 U.S.C. § 160","url":"https://www.law.cornell.edu/uscode/text/29/160","subs":["(c)","(e)","(a)"],"stext":{"head":"§160. Prevention of unfair labor practices","paras":[[0,"(a) Powers of Board generally"],[0,"The Board is empowered, as hereinafter provided, to prevent any person from engaging in any unfair labor practice (listed in section 158 of this title) affecting commerce. This power shall not be affected by any other means of adjustment or prevention that has been or may be established by agreement, law, or otherwise: Provided, That the Board is empowered by agreement with any agency of any State or Territory to cede to such agency jurisdiction over any cases in any industry (other than mining, manufacturing, communications, and transportation except where predominantly local in character) even though such cases may involve labor disputes affecting commerce, unless the provision of the State or Territorial statute applicable to the determination of such cases by such agency is inconsistent with the corresponding provision of this subchapter or has received a construction inconsistent therewith."],[0,"(b) Complaint and notice of hearing; answer; court rules of evidence inapplicable"],[0,"Whenever it is charged that any person has engaged in or is engaging in any such unfair labor practice, the Board, or any agent or agency designated by the Board for such purposes, shall have power to issue and cause to be served upon such person a complaint stating the charges in that respect, and containing a notice of hearing before the Board or a member thereof, or before a designated agent or agency, at a place therein fixed, not less than five days after the serving of said complaint: Provided, That no complaint shall issue based upon any unfair labor practice occurring more than six months prior to the filing of the charge with the Board and the service of a copy thereof upon the person against whom such charge is made, unless the person aggrieved thereby was prevented from filing such charge by reason of service in the armed forces, in which event the six-month period shall be computed from the day of his discharge. Any such complaint may be amended by the member, agent, or agency conducting the hearing or the Board in its discretion at any time prior to the issuance of an order based thereon. The person so complained of shall have the right to file an answer to the original or amended complaint and to appear in person or otherwise and give testimony at the place and time fixed in the complaint. In the discretion of the member, agent, or agency conducting the hearing or the Board, any other person may be allowed to intervene in the said proceeding and to present testimony. Any such proceeding shall, so far as practicable, be conducted in accordance with the rules of evidence applicable in the district courts of the United States under the rules of civil procedure for the district courts of the United States, adopted by the Supreme Court of the United States pursuant to section 2072 of title 28."],[0,"(c) Reduction of testimony to writing; findings and orders of Board"],[0,"The testimony taken by such member, agent, or agency or the Board shall be reduced to writing and filed with the Board. Thereafter, in its discretion, the Board upon notice may take further testimony or hear argument. If upon the preponderance of the testimony taken the Board shall be of the opinion that any person named in the complaint has engaged in or is engaging in any such unfair labor practice, then the Board shall state its findings of fact and shall issue and cause to be served on such person an order requiring such person to cease and desist from such unfair labor practice, and to take such affirmative action including reinstatement of employees with or without back pay, as will effectuate the policies of this subchapter: Provided, That where an order directs reinstatement of an employee, back pay may be required of the employer or labor organization, as the case may be, responsible for the discrimination suffered by him: And provided further, That in determining whether a complaint shall issue alleging a violation of subsection (a)(1) or (a)(2) of section 158 of this title, and in deciding such cases, the same regulations and rules of decision shall apply irrespective of whether or not the labor organization affected is affiliated with a labor organization national or international in scope. Such order may further require such person to make reports from time to time showing the extent to which it has complied with the order. If upon the preponderance of the testimony taken the Board shall not be of the opinion that the person named in the complaint has engaged in or is engaging in any such unfair labor practice, then the Board shall state its findings of fact and shall issue an order dismissing the said complaint. No order of the Board shall require the reinstatement of any individual as an employee who has been suspended or discharged, or the payment to him of any back pay, if such individual was suspended or discharged for cause. In case the evidence is presented before a member of the Board, or before an administrative law judge or judges thereof, such member, or such judge or judges as the case may be, shall issue and cause to be served on the parties to the proceeding a proposed report, together with a recommended order, which shall be filed with the Board, and if no exceptions are filed within twenty days after service thereof upon such parties, or within such further period as the Board may authorize, such recommended order shall become the order of the Board and become effective as therein prescribed."],[0,"(d) Modification of findings or orders prior to filing record in court"],[0,"Until the record in a case shall have been filed in a court, as hereinafter provided, the Board may at any time upon reasonable notice and in such manner as it shall deem proper, modify or set aside, in whole or in part, any finding or order made or issued by it."],[0,"(e) Petition to court for enforcement of order; proceedings; review of judgment"],[0,"The Board shall have power to petition any court of appeals of the United States, or if all the courts of appeals to which application may be made are in vacation, any district court of the United States, within any circuit or district, respectively, wherein the unfair labor practice in question occurred or wherein such person resides or transacts business, for the enforcement of such order and for appropriate temporary relief or restraining order, and shall file in the court the record in the proceedings, as provided in section 2112 of title 28. Upon the filing of such petition, the court shall cause notice thereof to be served upon such person, and thereupon shall have jurisdiction of the proceeding and of the question determined therein, and shall have power to grant such temporary relief or restraining order as it deems just and proper, and to make and enter a decree enforcing, modifying and enforcing as so modified, or setting aside in whole or in part the order of the Board. No objection that has not been urged before the Board, its member, agent, or agency, shall be considered by the court, unless the failure or neglect to urge such objection shall be excused because of extraordinary circumstances. The findings of the Board with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall be conclusive. If either party shall apply to the court for leave to adduce additional evidence and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the hearing before the Board, its member, agent, or agency, the court may order such additional evidence to be taken before the Board, its member, agent, or agency, and to be made a part of the record. The Board may modify its findings as to the facts, or make new findings by reason of additional evidence so taken and filed, and it shall file such modified or new findings, which findings with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall be conclusive, and shall file its recommendations, if any, for the modification or setting aside of its original order. Upon the filing of the record with it the jurisdiction of the court shall be exclusive and its judgment and decree shall be final, except that the same shall be subject to review by the appropriate United States court of appeals if application was made to the district court as hereinabove provided, and by the Supreme Court of the United States upon writ of certiorari or certification as provided in section 1254 of title 28."],[0,"(f) Review of final order of Board on petition to court"],[0,"Any person aggrieved by a final order of the Board granting or denying in whole or in part the relief sought may obtain a review of such order in any United States court of appeals in the circuit wherein the unfair labor practice in question was alleged to have been engaged in or wherein such person resides or transacts business, or in the United States Court of Appeals for the District of Columbia, by filing in such a court a written petition praying that the order of the Board be modified or set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Board, and thereupon the aggrieved party shall file in the court the record in the proceeding, certified by the Board, as provided in section 2112 of title 28. Upon the filing of such petition, the court shall proceed in the same manner as in the case of an application by the Board under subsection (e), and shall have the same jurisdiction to grant to the Board such temporary relief or restraining order as it deems just and proper, and in like manner to make and enter a decree enforcing, modifying, and enforcing as so modified, or setting aside in whole or in part the order of the Board; the findings of the Board with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall in like manner be conclusive."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/160?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":1,"head":"§160. Prevention of unfair labor practices","tname":"Labor","by":{"0":"4","1":"3, 3","2":"5, 14, 42, 43"}},{"t":"case","label":"Allen v. United States","cite":"164 U.S. 492","y":1896,"id":"scdb/1896-052","sc":1,"sum":"There is no error in an instruction that evidence recited by the court to the jury leaves them at liberty to infer not only wilfulness, but malice aforethought,-.if the evidence is as so recited.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"American Ship Building Co. v. NLRB","cite":"380 U.S. 300","y":1965,"id":"1964/255","sc":1,"op":1,"sum":"An employer does not commit an unfair labor practice under either § 8 (a) (1) or § 8 (a) (3) of the Act when, after an impasse has been reached in negotiations, he temporarily shuts down his plant and lays off his employees for the sole purpose of applying economic pressure in support of his legitimate bargaining position. Pp. 308-318. 118 U. S. App. D. C. 78, 331 F. 2d 839, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15, 18"}},{"t":"case","label":"American Steel Foundries v. Tri-City Central Trades Council","cite":"257 U.S. 184","y":1921,"id":"scdb/1921-024","sc":1,"sum":"1. A decree of injunction in a labor controversy was entered in the District Court before the date of the Clayton Act, e. 323, 38 Stat. 738, but was pending on appeal in 'the Circuit Court of Appeals when the act was approved. Held, that the plaintiff had no vested right in the decree, and that the act was to be regarded in determining the appeal.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"17","2":"3"}},{"t":"case","label":"Atlantic Richfield Co. v. Christian","cite":"140 S. Ct. 1335","y":2020,"id":"2019/17-1498","sc":1,"op":1,"sum":"The Court held that the landowners in this case were potentially responsible parties under the Comprehensive Environmental Response, Compensation, and Liability Act (CERCLA) and thus need the Environmental Protection Agency’s approval to take remedial action.","sumSrc":"Oyez","by":{"1":"31","3":"13"}},{"t":"case","label":"(III) Cases—Continued: Beth Israel Hospital v. NLRB","cite":"437 U.S. 483","y":1978,"id":"1977/77-152","sc":1,"op":1,"sum":"The Court held that, since 1974, the Act provided employees of nonprofit healthcare institutions with the right to self-organize and bargain collectively, including the right to communicate about the topic at the jobsite. However, an employer may curb that right by showing that special circumstances necessitate the prohibition of communication in order to maintain production or discipline.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Boys Markets, Inc. v. Retail Clerks","cite":"398 U.S. 235","y":1970,"id":"1969/768","sc":1,"sum":"In the circumstances of this case-where the grievance was subject to arbitration under the collectivebargaining agreement, petitioner was ready for arbitration when the strike was enjoined, and the District Court concluded that respondent's violations of the no-strike clause were causing petitioner irreparable injury--the Norris-LaGuardia Act does not bar the granting of injunctive relief. Sinclair Refining Co. v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Bravo v. Dolsen Cos.","cite":"888 P.2d 147","y":1995,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/888/147/","op":1,"by":{"1":"20"}},{"t":"case","label":"Brown v. Hotel Employees","cite":"468 U.S. 491","y":1984,"id":"1983/83-498","sc":1,"op":1,"sum":"Section 9 of the New Jersey Casino Control Act requires annual registration of unions representing persons employed in casinos or casino hotels, and provides that a union may be prohibited from receiving dues from such employees and from administering any pension or welfare funds if any union officer is disqualified under the criteria contained in §86 for the licensing of various entities and persons. Those criteria …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3, 29","2":"6, 7, 32","3":"10"}},{"t":"case","label":"Buckman Co. v. Plaintiffs’ Legal Committee","cite":"531 U.S. 341","y":2001,"id":"2000/98-1768","sc":1,"sum":"The Court held that the plaintiffs' state-law fraud-on-the-FDA claims conflicted with, and were therefore pre-empted by, the FDCA, as amended by the MDA. \"The conflict,\" wrote Chief Justice Rehnquist for the Court, \"stems from the fact that the federal statutory scheme amply empowers the FDA to punish and deter fraud against the Agency, and that this authority is used by the Agency to achieve a somewhat delicate balance of statutory objectives.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Building & Construction Trades Council v. Associated Builders & Contractors of Massachusetts/Rhode Island, Inc.","cite":"507 U.S. 218","y":1993,"id":"1992/91-261","sc":1,"sum":"The NLRA does not pre-empt enforcement by a state authority, acting as the owner of a construction project, of an otherwise lawful Cite as: 507 U. S. 218 (1993) prehire collective-bargaining agreement negotiated by private parties. This Court has articulated two distinct NLRA pre-emption principles: \"Garmon pre-emption\" forbids state and local regulation of activities that are protected by § 7 of the NLRA or …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Bus Employees v. Wisconsin Employment Relations Board","cite":"340 U.S. 383","y":1951,"id":"scdb/1950-032","sc":1,"sum":"The Wisconsin Public Utility Anti-Strike Law, which makes it a misdemeanor for any group of public utility employees to engage in a strike which would cause an interruption of an essential publicutility service, as applied in these cases, conflicts with the National Labor Relations Act, as amended by the Labor Management Relations Act, 1947, and is invalid under the Supremacy Clause of the Federal Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12","2":"21, 42"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"op":2,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Davis Supermarkets, Inc. v. NLRB","cite":"2 F.3d 1162","y":1993,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/2/1162/","op":1,"ar":1,"by":{"1":"26","2":"13, 18, 19","3":"20"}},{"t":"case","label":"East Chicago Rehabilitation Center, Inc. v. NLRB","cite":"710 F.2d 397","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/710/397/","by":{"1":"16"}},{"t":"case","label":"Garner v. Teamsters","cite":"346 U.S. 485","y":1953,"id":"scdb/1953-019","sc":1,"op":3,"sum":"Petitioners' grievance was within the jurisdiction of the National Labor Relations Board to prevent unfair labor practices under the Labor Management Relations Act, and was not subject to relief by injunction in the state courts.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28","2":"5, 40"}},{"t":"case","label":"Gibbons v. Ogden","cite":"9 Wheat. 1","y":1824,"url":"https://www.courtlistener.com/c/Wheat./9/1/","by":{"1":"3"}},{"t":"case","label":"International Paper Co. v. Ouellette","cite":"479 U.S. 481","y":1987,"id":"1986/85-1233","sc":1,"sum":"The Clean Water Act (Act) prohibits the discharge of effluents into navigable waters unless the point source has obtained a permit from the Environmental Protection Agency (EPA). The Act also allows the State in which the point source is located (the \"source State\") to impose more stringent discharge limitations than the federal ones, and even to administer its own permit program if certain requirements are met. In …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31","3":"13"}},{"t":"case","label":"Iron Workers v. Perko","cite":"373 U.S. 701","y":1963,"id":"1962/482","sc":1,"op":1,"sum":"The case arguably involved an unfair labor practice over which the National Labor Relations Board would have exclusive jurisdiction, and the State Court was precluded from exercising jurisdiction. San Diego Building Trades Council v. Garmon, 359 U. S. 236, followed. InternationalAssn. of Machinists v. Gonzales, 356 U. S. 617, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Marine Engineers v. Interlake S.S. Co.","cite":"370 U.S. 173","y":1962,"id":"1961/166","sc":1,"op":2,"sum":"The dispute was arguably within the jurisdiction of the National Labor Relations Board, and, therefore, the State Court was precluded from exercising jurisdiction. San Diego Building Trades Council v. Garmon, 359 U. S. 236.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5, 27","2":"7","3":"21"}},{"t":"case","label":"NLRB v. Allis-Chalmers Manufacturing Co.","cite":"388 U.S. 175","y":1967,"id":"1966/216","sc":1,"sum":"Lawful economic strikes were called at two of respondent AllisChalmers' plants in accordance with duly authorized union procedures by the locals of the union representing the employees. Some union members crossed picket lines and worked during the strikes. After the strikes were over the locals brought proceedings against these members, imposed fines of $20 to $100, and sued in state courts to collect the fines. The …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12"}},{"t":"case","label":"NLRB v. Erie Resistor Corp.","cite":"373 U.S. 221","y":1963,"id":"1962/288","sc":1,"op":3,"sum":"Even in the absence of a finding of specific illegal intent and notwithstanding the employer's claim that his action was necessary to continue his operations during a strike, the National Labor Relations Board was justified in finding that it was a violation of § 8 (a) of the National Labor Relations Act for the employer to discriminate between employees who struck and employees who worked during a strike by …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16","2":"3, 21, 40"}},{"t":"case","label":"NLRB v. Gissel Packing Co.","cite":"395 U.S. 575","y":1969,"id":"1968/573","sc":1,"sum":"In Nos. 573 and 691, Unions waged organizational campaigns, obtained authorization cards from a majority of employees in the appropriate bargaining units, and demanded recognition by the employers. The employers refused to bargain, on the ground that the cards were inherently unreliable, and carried out vigorous antiunion campaigns. In one instance the Union did not seek a representation election but filed unfair …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"NLRB v. Insurance Agents","cite":"361 U.S. 477","y":1960,"id":"1959/15","sc":1,"op":1,"sum":"Such tactics would not support a finding by the Board that the union had failed to bargain in good faith as required by § 8 (b) (3). Pp. 478-500. (1) The basic premise of the duty of collective bargaining required in the Act is that it is a process in which the parties deal with each other in a serious, good-faith desire to reach agreement and to enter into a contract ordering their industrial relationship. Congress …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"NLRB v. J. Weingarten, Inc.","cite":"420 U.S. 251","y":1975,"id":"1974/73-1363","sc":1,"sum":"The employer violated § 8 (a) (1) of the National Labor Relations Act because it interfered with, restrained, and coerced the individual right of an employee, protected by § 7, \"to engage in... concerted activities for... mutual aid or protection... Y' when it denied the employee's request for the presence of her union representative at the investigatory interview that the employee reasonably believed would result …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"NLRB v. Mackay Radio & Telegraph Co.","cite":"304 U.S. 333","y":1938,"id":"scdb/1937-067","sc":1,"sum":"(1) Under the findings, the strike was a consequence of, or in connection with, a \"labor dispute\" as defined in § 2 (9) of the National Labor Relations Act. It was not necessary for the Board to find what the state of the negotiations was when the strike was called; nor, in so many words, that a \"labor dispute\" existed. P. 344. - (2) Their work having ceased as a consequence of, or in connection with, a current …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"NLRB v. Reynolds & Manley Lumber Co.","cite":"212 F.2d 155","y":1954,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/212/155/","by":{"1":"16","2":"29"}},{"t":"case","label":"NLRB v. Special Touch Home Care Services, Inc.","cite":"708 F.3d 447","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/708/447/","op":1,"by":{"1":"16"}},{"t":"case","label":"NLRB v. Teamsters","cite":"362 U.S. 274","y":1960,"id":"1959/34","sc":1,"op":2,"sum":"Peaceful picketing by a labor union, which. does not represent a majority of the employees, to compel the employer to recognize the union as the exclusive bargaining agent of its employees, is not conduct of the union \"to restrain or coerce\" the employees in the exercise of rights guaranteed in g 7 of the National Labor Relations Act, as amended, and therefore such picketing is not an unfair labor practice under § 8 …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13","2":"46","3":"4"}},{"t":"case","label":"Southern S.S. Co. v. NLRB","cite":"316 U.S. 31","y":1942,"id":"scdb/1941-035","sc":1,"sum":"1. The National Labor Relations Board is not obliged to permit the presence of a representative of the employer at an election by the employees of their bargaining representative.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Vegelahn v. Guntner","cite":"44 N.E. 1077","y":1896,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./44/1077/","by":{"1":"14"}},{"t":"case","label":"Wisconsin Department of Industry, Labor & Human Relations v. Gould Inc.","cite":"475 U.S. 282","y":1986,"id":"1985/84-1484","sc":1,"op":1,"sum":"The NLRA pre-empts the Wisconsin debarment statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"usc","label":"29 U.S.C. § 153","url":"https://www.law.cornell.edu/uscode/text/29/153","subs":["(a)","(d)"],"stext":{"head":"§153. National Labor Relations Board","paras":[[0,"(a) Creation, composition, appointment, and tenure; Chairman; removal of members"],[0,"The National Labor Relations Board (hereinafter called the \"Board\") created by this subchapter prior to its amendment by the Labor Management Relations Act, 1947 [29 U.S.C. 141 et seq.], is continued as an agency of the United States, except that the Board shall consist of five instead of three members, appointed by the President by and with the advice and consent of the Senate. Of the two additional members so provided for, one shall be appointed for a term of five years and the other for a term of two years. Their successors, and the successors of the other members, shall be appointed for terms of five years each, excepting that any individual chosen to fill a vacancy shall be appointed only for the unexpired term of the member whom he shall succeed. The President shall designate one member to serve as Chairman of the Board. Any member of the Board may be removed by the President, upon notice and hearing, for neglect of duty or malfeasance in office, but for no other cause."],[0,"(b) Delegation of powers to members and regional directors; review and stay of actions of regional directors; quorum; seal"],[0,"The Board is authorized to delegate to any group of three or more members any or all of the powers which it may itself exercise. The Board is also authorized to delegate to its regional directors its powers under section 159 of this title to determine the unit appropriate for the purpose of collective bargaining, to investigate and provide for hearings, and determine whether a question of representation exists, and to direct an election or take a secret ballot under subsection (c) or (e) of section 159 of this title and certify the results thereof, except that upon the filing of a request therefor with the Board by any interested person, the Board may review any action of a regional director delegated to him under this paragraph, but such a review shall not, unless specifically ordered by the Board, operate as a stay of any action taken by the regional director. A vacancy in the Board shall not impair the right of the remaining members to exercise all of the powers of the Board, and three members of the Board shall, at all times, constitute a quorum of the Board, except that two members shall constitute a quorum of any group designated pursuant to the first sentence hereof. The Board shall have an official seal which shall be judicially noticed."],[0,"(c) Annual reports to Congress and the President"],[0,"The Board shall at the close of each fiscal year make a report in writing to Congress and to the President summarizing significant case activities and operations for that fiscal year."],[0,"(d) General Counsel; appointment and tenure; powers and duties; vacancy"],[0,"There shall be a General Counsel of the Board who shall be appointed by the President, by and with the advice and consent of the Senate, for a term of four years. The General Counsel of the Board shall exercise general supervision over all attorneys employed by the Board (other than administrative law judges and legal assistants to Board members) and over the officers and employees in the regional offices. He shall have final authority, on behalf of the Board, in respect of the investigation of charges and issuance of complaints under section 160 of this title, and in respect of the prosecution of such complaints before the Board, and shall have such other duties as the Board may prescribe or as may be provided by law. In case of a vacancy in the office of the General Counsel the President is authorized to designate the officer or employee who shall act as General Counsel during such vacancy, but no person or persons so designated shall so act (1) for more than forty days when the Congress is in session unless a nomination to fill such vacancy shall have been submitted to the Senate, or (2) after the adjournment sine die of the session of the Senate in which such nomination was submitted."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/153?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§153. National Labor Relations Board","tname":"Labor","by":{"1":"2, 2, 2","2":"5, 19"}},{"t":"usc","label":"29 U.S.C. § 163","url":"https://www.law.cornell.edu/uscode/text/29/163","stext":{"head":"§163. Right to strike preserved","paras":[[0,"Nothing in this subchapter, except as specifically provided for herein, shall be construed so as either to interfere with or impede or diminish in any way the right to strike, or to affect the limitations or qualifications on that right."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/163?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§163. Right to strike preserved","tname":"Labor","by":{"1":"2, 26","2":"1, 3, 4, 21, 46","3":"4, 7"}},{"t":"case","label":"Andrewsikas v. Supreme Indus., Inc.","cite":"2021 WL 1090786","y":2021,"court":"D. Conn. Mar. 22","by":{"2":"41"}},{"t":"case","label":"Andrus v. Allard","cite":"444 U.S. 51","y":1979,"id":"1979/78-740","sc":1,"sum":"The Eagle Protection Act makes it unlawful to \"take, possess, sell, purchase, barter, offer to sell, purchase or barter, transport, export or import\" bald or golden eagles or any part thereof, with the proviso that the prohibition does not apply to \"possession or transportation\" of such eagles or parts thereof taken prior to the effective date of the Act. Similarly, the Migratory Bird Treaty Act makes it unlawful to …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"49"}},{"t":"case","label":"Apex Hosiery Co. v. Leader","cite":"310 U.S. 469","y":1940,"id":"scdb/1939-041","sc":1,"sum":"Members of a labor union, bent on unionizing a hosiery factory in which but a few of them were employed, forcibly, aid in violation of civil and criminal laws of the State, took possession of the plant and held it during a protracted \"sit-down\" strike, during which much of the machinery was willfully injured or destroyed and during which the business, largely interstate, was.entirely suspended. When the plant was …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"38"}},{"t":"case","label":"Ashwander v. TVA","cite":"297 U.S. 288","y":1936,"id":"1900-1940/297us288","sc":1,"sum":"The Court held that Congress did not abuse its power with the TVA. Justice Hughes argued that the Wilson Dam, the location where the TVA was in the business of generating electricity, had been built originally in the interest of national defense: it produced materials involved in munitions manufacture. The government could sell excess electricity to consumers without violating the Constitution.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"Belknap, Inc. v. Hale","cite":"463 U.S. 491","y":1983,"id":"1982/81-1966","sc":1,"sum":"Respondents' causes of action for misrepresentation and breach of contract are not pre-empted.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"40"}},{"t":"case","label":"Bus Employees v. Missouri","cite":"374 U.S. 74","y":1963,"id":"1962/604","sc":1,"sum":"Proceeding under a Missouri statute, the Governor of Missouri proclaimed that the public interest, health and welfare were jeopardized by a threatened strike against a public transit company in the State and issued executive orders taking possession of the company and directing that it continue operations. However, the employees of the company did not become employees of the State; the State did not pay their wages …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"1, 21"}},{"t":"case","label":"Coventry Health Care of Mo., Inc. v. Nevils","cite":"581 U.S. 87","y":2017,"id":"2016/16-149","sc":1,"sum":"The Court determined that the Federal Employees Health Benefits Act (FEHBA) preempts state laws that prohibit insurance companies from claiming the proceeds of personal injury settlements pursuant to their contracts, and the express preemption clause of the FEHBA does not violate the Supremacy Clause.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Dayton Newspapers, Inc. v. NLRB","cite":"402 F.3d 651","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/402/651/","by":{"2":"23, 27"}},{"t":"case","label":"Elgin v. Dep’t of Treasury","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"sum":"The Court held that the Civil Service Reform Act precludes federal courts' jurisdiction in cases where federal employees seek equitable relief.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"Golden State Transit Corp. v. Los Angeles","cite":"475 U.S. 608","y":1986,"id":"1985/84-1644","sc":1,"sum":"The city's action in conditioning petitioner's franchise renewal on the settlement of the labor dispute is pre-empted by the NLRA.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"Guss v. Utah Lab. Rels. Bd.","cite":"353 U.S. 1","y":1957,"id":"1956/280","sc":1,"ar":1,"by":{"2":"43"}},{"t":"case","label":"Hamdan v. Rumsfeld","cite":"548 U.S. 557","y":2006,"id":"2005/05-184","sc":1,"sum":"The Court found that the rights given by the Geneva Convention to prisoners of war could be enforced by federal court.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"Hanna Mining Co. v. District 2, Marine Eng’rs Beneficial Ass’n","cite":"382 U.S. 181","y":1965,"id":"1965/7","sc":1,"ar":1,"sum":"While a state may not regulate conduct arguably protected or prohibited by the NLRA, the Supreme Court found that Hanna's engineers were supervisors, not employees, and were not covered under the Act. The NLRA did not preempt Wisconsin's authority in this situation. The Court reversed the lower court decision and remanded the case to the Supreme Court of Wisconsin.","sumSrc":"Oyez","by":{"2":"6, 45","3":"21"}},{"t":"case","label":"Hrones v. Rideout Mem’l Hosp.","cite":"2022 WL 159034","y":2022,"court":"E.D. Cal. Jan. 18","by":{"2":"40"}},{"t":"case","label":"Incres S.S. Co. v. Int’l Mar. Workers Union","cite":"372 U.S. 24","y":1963,"id":"1962/33","sc":1,"sum":"The National Labor Relations Act is inapplicable to the maritime operations of foreign-flag ships employing alien seamen, McCulloch v. Sociedad Nacional,ante, p. 10, and it did not deprive the State Court of jurisdiction to grant such relief. Pp. 24-28. 10 N. Y. 2d 218, 176 N. E. 2d 719, judgment vacated and cause remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"45"}},{"t":"case","label":"Int’l Bhd. of Boilermakers v. Hardeman","cite":"401 U.S. 233","y":1971,"id":"1970/123","sc":1,"sum":"Respondent, who was a member of petitioner union, assaulted the business manager of his local for allegedly failing to refer him for a job, and was tried for this tonduct by the union on charges of (1) creating dissension and working against the interest and harmony of the local, which carried a penalty of expulsion, and (2) threatening and using force to restrain an officer from discharging the duties of his union …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"op":1,"sum":"In a seven-member majority opinion written by Justice Stephen G. Breyer, the Court upheld the Federal Circuit ruling that the statute of limitations was \"jurisdictional,\" or a predicate for court authority. Breyer referred to roughly five decades of the Court's case law to determine that the doctrine of stare decisis required it to follow the time limit and dismiss John R. Sand's claim.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Judkins v. Sadler-Mac Neil","cite":"376 P.2d 837","y":1962,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/376/837/","by":{"2":"35"}},{"t":"case","label":"Local 189, Amalgamated Meat Cutters v. Jewel Tea Co.","cite":"381 U.S. 676","y":1965,"id":"1964/240","sc":1,"sum":"The judgment is reversed. Pp. 679-735. 331 F. 2d 547, reversed. MR. JUSTICE WHITE, joined by THE CHIEF JUSTICE and MR. JUSTICE BRENNAN, concluded, that:.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"Local 926, Int’l Union of Operating Eng’rs v. Jones","cite":"460 U.S. 669","y":1983,"id":"1982/81-1574","sc":1,"sum":"Respondent's state-court action against the Union is pre-empted by the National Labor Relations Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Local 438 Constr. Union v. Curry","cite":"371 U.S. 542","y":1963,"id":"1962/87","sc":1,"sum":"Respondents sued in a Georgia state court to enjoin a labor union from picketing the site where they were engaged in construction work. They alleged that the picketing was for the purpose of forcing them to hire only union labor and that it violated the Georgia fight-to-work statute. The union contended that its picketing was for the sole purpose of publicizing the facts about the wages paid by respondents and that …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Lucas v. S.C. Coastal Council","cite":"505 U.S. 1003","y":1992,"id":"1991/91-453","sc":1,"sum":"In a 6-to-2 decision, the Court relied on the trial court's finding that Lucas's lots had been rendered valueless by the state law. \"[W]hen the owner of real property has been called upon to sacrifice all economically beneficial uses in the name of the common good...he has suffered a taking.\".","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Marquez v. Screen Actors Guild, Inc.","cite":"525 U.S. 33","y":1998,"id":"1998/97-1056","sc":1,"sum":"Announced by Justice Sandra Day O'Connor, the Court ruled collective bargaining contracts do not have to spell out what it means to be \"in good standing.\" Justice O'Conner noted that requiring membership to be specified in a contract would force all terms to be specified. There would be no limit.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"McGirt v. Oklahoma","cite":"140 S. Ct. 2452","y":2020,"id":"2019/18-9526","sc":1,"sum":"The Court held that parts of eastern Oklahoma are an Indian reservation subject to exclusive federal jurisdiction for certain crimes under the Indian Major Crimes Act.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"Moreno v. UtiliQuest, LLC","cite":"29 F.4th 567","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/29/567/","by":{"2":"40"}},{"t":"case","label":"Murphy v. NCAA","cite":"138 S. Ct. 1461","y":2018,"id":"2017/16-476","sc":1,"sum":"The Court decided that provisions of the Professional and Amateur Sports Protection Act (PASPA) that prohibit state authorization and licensing of sports gambling schemes violate the Constitution’s anticommandeering rule, and that no other PASPA provisions are severable from the provisions at issue.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"N. Pac. Ry. v. Solum","cite":"247 U.S. 477","y":1918,"id":"scdb/1917-130","sc":1,"sum":"The duty of a carrier to ship by the cheapest route in the absence of shipping instructions is not absolute; it is a duty to deal fairly with the shipper, with due regard also for the carrier’s own interest and its obligation to the public.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"NAACP v. Claiborne Hardware Co.","cite":"458 U.S. 886","y":1982,"id":"1981/81-202","sc":1,"sum":"The Court held that the NAACP's nonviolent protest was protected by the First Amendment.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"NLRB v. Donna-Lee Sportswear Co.","cite":"836 F.2d 31","y":1987,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/836/31/","by":{"2":"44"}},{"t":"case","label":"NLRB v. Heyman","cite":"541 F.2d 796","y":1976,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/541/796/","by":{"2":"44"}},{"t":"case","label":"NLRB v. Jones & Laughlin Steel Corp.","cite":"301 U.S. 1","y":1937,"id":"1900-1940/301us1","sc":1,"sum":"The Court found that the Commerce Clause gave the government the right to regulate labor-management disputes.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"NLRB v. Strong","cite":"393 U.S. 357","y":1969,"id":"1968/61","sc":1,"sum":"The NLRB's authority under the Act to remedy the unfair labor practice which occurred when respondent refused to sign the collective bargaining agreement negotiated on his behalf included the power to require payment of the fringe benefits under the NLRB's remedial authority to take \"affirmative action including reinstatement of employees with or without back pay,\" § 10 (c), which is not \"affected by any other means …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"44"}},{"t":"case","label":"NLRB v. UFCW, Local 23","cite":"484 U.S. 112","y":1987,"id":"1987/86-594","sc":1,"op":1,"sum":"National Labor Relations Board regulations implementing the unfair labor practice provisions of the National Labor Relations Act (NLRA or Act) provide that, after one of the Board's regional directors has filed a complaint but before a hearing is held thereon, the director may enter into either a formal or an informal settlement. The regulations allow a nonconsenting party to appeal a formal settlement to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"NLRB v. Wash. Aluminum Co.","cite":"370 U.S. 9","y":1962,"id":"1961/464","sc":1,"op":1,"sum":"The Board correctly interpreted and applied the Act to the circumstances of this case, and the Court of Appeals should have enforced its order.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27, 34"}},{"t":"case","label":"Noll v. Am. Biltrite Inc.","cite":"395 P.3d 1021","y":2017,"court":"Wash.","url":"https://www.courtlistener.com/c/P.3d/395/1021/","by":{"2":"11"}},{"t":"case","label":"Patterson v. Alabama","cite":"294 U.S. 600","y":1935,"id":"scdb/1934-165","sc":1,"sum":"1. Upon review of a judgment of a state court disposing of the case on a point of local practice without adjudicating a claim of federal right, this Court must examine the record and determine whether the non-federal ground is adequate to sustain the judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Radcliffe v. Rainbow Constr. Co.","cite":"254 F.3d 772","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/254/772/","by":{"2":"41"}},{"t":"case","label":"Retail Clerks Int’l Ass’n, Local 1625 v. Schermerhorn","cite":"373 U.S. 746","y":1963,"id":"1962/368","sc":1,"op":1,"sum":"Petitioner union and an employer in Florida entered into a collective bargaining agreement containing an \"agency shop\" clause, which left union membership optional with the employees but required that, as a condition of continued employment, nonunion employees pay to the union sums equal to the initiation fees and periodic dues paid by union members. Nonunion employees of the employer sued in a Florida State Court …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"45"}},{"t":"case","label":"Spector v. Norwegian Cruise Line Ltd.","cite":"545 U.S. 119","y":2005,"id":"2004/03-1388","sc":1,"sum":"The Court held 6-3 that Title III applied to foreign-flag cruise ships in U.S. waters. Justice Kennedy delivered the Court's controlling opinion, which held that Title III did not apply to foreign ships' internal affairs, because there was no \"clear congressional statement\" showing an intent to do so. A clear statement was necessary before a general law could interfere with a foreign-vessel's internal affairs.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"State v. Nw. Magnesite Co.","cite":"182 P.2d 643","y":1947,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/182/643/","by":{"2":"11"}},{"t":"case","label":"Tex. & Pac. Ry. v. Abilene Cotton Oil Co.","cite":"204 U.S. 426","y":1907,"id":"scdb/1906-159","sc":1,"sum":"Where defendant in the state court contends that, consistently, with the Interstate Commerce Act, the state court hks no power to grant the relief, and such contention is essentially involved and expressly, and, in order to support the judgment, necessarily, decided adversely to the defendant, a Federal question exists and this court' can review the judgment on writ of error under § 709,'.Rev. Stat.'","sumSrc":"Headnote (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"UAW v. O’Brien","cite":"339 U.S. 454","y":1950,"id":"scdb/1949-071","sc":1,"sum":"The strike-vote provisions of the Michigan labor mediation law, Mich. Conip. Laws, 1948, §§ 423.1 et seq., which prohibit the calling of a strike unless a state-prescribed procedure for mediation is followed and unless a majority of the employees in a state-defined bargaining unit authorizes the strike in a state-conducted election, conflict with the National Labor Relations Act, as amended by the Labor Management …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21, 26, 28","3":"7"}},{"t":"case","label":"United Mine Workers v. Gibbs","cite":"383 U.S. 715","y":1966,"id":"1965/243","sc":1,"sum":"A coal company closed a mine in Tennessee and laid off miners belonging to one of petitioner's local unions. Thereafter the company, through a subsidiary, attempted to open a new mine nearby with members of a rival union. Respondent was hired as mine superintendent and given a contract to truck coal to the nearest rail loading point. On August 15 and 16, 1960, armed members of petitioner's local forcibly prevented …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"34"}},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"sum":"The Court found that a police department's placement of a GPS tracking device on a man's Jeep without his knowledge was an illegal search under the Fourth Amendment.","sumSrc":"Oyez","by":{"2":"36"}},{"t":"case","label":"United States v. W. Pac. R.R.","cite":"352 U.S. 59","y":1956,"id":"1956/18","sc":1,"sum":"The three respondent railroads sued the United States in the Court of Claims under the Tucker Act to recover the difference between the tariff rates actually paid and those allegedly due on certain Army shipments of steel aerial bomb cases filled with napalm gel but without the bursters and fuses required to ignite them. The carriers claimed to be entitled to payment at the high firstclass rates established in Item …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"Vaca v. Sipes","cite":"386 U.S. 171","y":1967,"id":"1966/114","sc":1,"sum":"Petitioners, union officials, were sued in a state court by a union member who alleged wrongful discharge by his employer in violation of the collective bargaining agreement and the union's arbitrary refusal to take his grievance to arbitration under the fifth and final step of the bargaining agreement's grievance procedures. The employee, whose duties required strenuous activity, was discharged on the ground of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Wis. Emp’t Rels. Bd. v. Teamsters Local 200","cite":"66 N.W.2d 318","y":1954,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W.2d/66/318/","by":{"2":"44"}},{"t":"const","label":"Amendment V","clauses":[["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"15, 47, 48"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"2":"6, 19, 32, 45"}},{"t":"law","label":"Pub. L. No. 86-257","url":"https://www.govinfo.gov/link/statute/73/519","by":{"2":"3, 38"}},{"t":"law","label":"Pub. L. No. 80-101","by":{"2":"3"}},{"t":"law","label":"Pub. L. No. 93-360","url":"https://www.govinfo.gov/link/statute/88/395","by":{"2":"3"}},{"t":"usc","label":"29 U.S.C. § 104","url":"https://www.law.cornell.edu/uscode/text/29/104","subs":["(e)","(i)"],"by":{"2":"5, 47, 5, 47"}},{"t":"usc","label":"29 U.S.C. § 142","url":"https://www.law.cornell.edu/uscode/text/29/142","subs":["(2)"],"stext":{"head":"§142. Definitions","paras":[[0,"When used in this chapter—"],[1,"(1) The term \"industry affecting commerce\" means any industry or activity in commerce or in which a labor dispute would burden or obstruct commerce or tend to burden or obstruct commerce or the free flow of commerce."],[1,"(2) The term \"strike\" includes any strike or other concerted stoppage of work by employees (including a stoppage by reason of the expiration of a collective-bargaining agreement) and any concerted slowdown or other concerted interruption of operations by employees."],[1,"(3) The terms \"commerce\", \"labor disputes\", \"employer\", \"employee\", \"labor organization\", \"representative\", \"person\", and \"supervisor\" shall have the same meaning as when used in subchapter II of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/142?type=usc&year=mostrecent&link-type=html"},"head":"§142. Definitions","tname":"Labor","by":{"2":"passim","3":"12"}},{"t":"usc","label":"29 U.S.C. § 164","url":"https://www.law.cornell.edu/uscode/text/29/164","subs":["(b)","(c)","(c)(1)","(c)(2)"],"stext":{"head":"§164. Construction of provisions","paras":[[0,"(a) Supervisors as union members"],[0,"Nothing herein shall prohibit any individual employed as a supervisor from becoming or remaining a member of a labor organization, but no employer subject to this subchapter shall be compelled to deem individuals defined herein as supervisors as employees for the purpose of any law, either national or local, relating to collective bargaining."],[0,"(b) Agreements requiring union membership in violation of State law"],[0,"Nothing in this subchapter shall be construed as authorizing the execution or application of agreements requiring membership in a labor organization as a condition of employment in any State or Territory in which such execution or application is prohibited by State or Territorial law."],[0,"(c) Power of Board to decline jurisdiction of labor disputes; assertion of jurisdiction by State and Territorial courts"],[0,"(1) The Board, in its discretion, may, by rule of decision or by published rules adopted pursuant to subchapter II of chapter 5 of title 5, decline to assert jurisdiction over any labor dispute involving any class or category of employers, where, in the opinion of the Board, the effect of such labor dispute on commerce is not sufficiently substantial to warrant the exercise of its jurisdiction: Provided, That the Board shall not decline to assert jurisdiction over any labor dispute over which it would assert jurisdiction under the standards prevailing upon August 1, 1959."],[0,"(2) Nothing in this subchapter shall be deemed to prevent or bar any agency or the courts of any State or Territory (including the Commonwealth of Puerto Rico, Guam, and the Virgin Islands), from assuming and asserting jurisdiction over labor disputes over which the Board declines, pursuant to paragraph (1) of this subsection, to assert jurisdiction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/164?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§164. Construction of provisions","tname":"Labor","by":{"2":"5, 43, 5, 38, 42, 38, 42","3":"22"}},{"t":"usc","label":"29 U.S.C. § 187","url":"https://www.law.cornell.edu/uscode/text/29/187","stext":{"head":"§187. Unlawful activities or conduct; right to sue; jurisdiction; limitations; damages","paras":[[0,"(a) It shall be unlawful, for the purpose of this section only, in an industry or activity affecting commerce, for any labor organization to engage in any activity or conduct defined as an unfair labor practice in section 158(b)(4) of this title."],[0,"(b) Whoever shall be injured in his business or property by reason or 1 any violation of subsection (a) may sue therefor in any district court of the United States subject to the limitations and provisions of section 185 of this title without respect to the amount in controversy, or in any other court having jurisdiction of the parties, and shall recover the damages by him sustained and the cost of the suit."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/187?type=usc&year=mostrecent&link-type=html"},"head":"§187. Unlawful activities or conduct; right to sue; jurisdiction; limitations; damages","tname":"Labor","by":{"2":"5","3":"7"}},{"t":"usc","label":"29 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/29/523","subs":["(a)"],"by":{"2":"5, 43"}},{"t":"usc","label":"29 U.S.C. § 524","url":"https://www.law.cornell.edu/uscode/text/29/524","by":{"2":"5, 43, 47"}},{"t":"reg","label":"29 C.F.R. § 101.4","url":"https://www.ecfr.gov/current/title-29/section-101.4","by":{"2":"17, 18"}},{"t":"reg","label":"29 C.F.R. § 101.5","url":"https://www.ecfr.gov/current/title-29/section-101.5","by":{"2":"18"}},{"t":"reg","label":"29 C.F.R. § 101.6","url":"https://www.ecfr.gov/current/title-29/section-101.6","by":{"2":"18"}},{"t":"reg","label":"29 C.F.R. § 101.8","url":"https://www.ecfr.gov/current/title-29/section-101.8","by":{"2":"18"}},{"t":"case","label":"BE & K Constr. Co. v. NLRB","cite":"536 U.S. 516","y":2002,"id":"2001/01-518","sc":1,"sum":"The Court held that the Board lacked authority to assess liability under the standard of prosecuting an unsuccessful suit with a retaliatory motive.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Bill Johnson’s Rests., Inc. v. NLRB","cite":"660 F.2d 1335","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/660/1335/","by":{"3":"17, 19"}},{"t":"usc","label":"29 U.S.C. § 152","url":"https://www.law.cornell.edu/uscode/text/29/152","by":{"3":"22"}}]};